/** One talent as `data/talents/<class>.json` stores it (GENERATED by `scripts.wow_talents.build`). */
export interface TalentFileTalent {
  /** Blizzard's talent id (Game Data API). */
  id: number;
  name: string;
  /** Row, 0 (top) to 6. */
  tier: number;
  /** Column, 0 to 3. */
  column: number;
  /** Icon file data id; 0 = no icon. */
  icon: number;
  /** The rank-1 spell. */
  spell: number;
  /** Each rank's tooltip, as the live game shows it. */
  ranks: string[];
  /** `[talent id, rank needed]` pairs (rank 1-based). */
  prereqs: number[][];
  /** Classic has no talent like it (no shared rank-1 spell or name). */
  newInForever?: boolean;
}
